<script setup lang="ts">
import { computed, onMounted, ref, reactive } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { profileRequest } from '../api'
import OnlineWebCapture from './OnlineWebCapture.vue'
import GameMetricCapture from './GameMetricCapture.vue'
import RankingMetricColumns from './RankingMetricColumns.vue'
import RankingMetricEvidence from './RankingMetricEvidence.vue'
import { useObservationMetrics } from '../composables/observationMetrics'

const base='/api/v1/admin/capture-workspace'
const overseas=ref<any>(null),sourceSession=ref<any>(null),maintenanceOpen=ref(false)
const sessionNeedsLogin=computed(()=>sourceSession.value?.status==='LOGIN_REQUIRED')
const sessionReviewDue=computed(()=>!!sourceSession.value?.reviewAfter&&Date.now()>=Date.parse(sourceSession.value.reviewAfter))
const data=ref<any>(null),runs=ref<any[]>([]),jobs=ref<any[]>([]),tab=ref('targets'),busy=ref(false),error=ref(''),search=ref(''),failuresOnly=ref(false)
const detail=ref<any>(null),detailOpen=ref(false),page=ref(1),job=ref<any>(null),jobOpen=ref(false),editOpen=ref(false),scheduleOpen=ref(false)
const publicObservationId=ref<number|undefined>(),publicProfiles=ref<any>(null),publicProfileBusy=ref(false)
const {rows:observationMetrics,loading:observationMetricsLoading,error:observationMetricsError,refresh:refreshObservationMetrics}=useObservationMetrics(()=>detailOpen.value?detail.value?.id:undefined)
const metricRow=ref<any>(null),metricOpen=ref(false)
function inspectMetric(row:any){metricRow.value=row;metricOpen.value=true}
const editKey=ref(''),editingImplemented=ref(false)
const form=reactive({name:'',url:'',fields:'',notes:'',toolKey:'http-html',enabled:false,revision:0})
const schedule=reactive({enabled:false,frequency:'twice',revision:0})
const labels:Record<string,string>={SUCCEEDED:'完整',PARTIAL:'不完整',FAILED:'失败',RUNNING:'运行中',INTERRUPTED:'中断',OPEN:'待诊断',NEEDS_LOGIN:'需要重新登录',AI_RUNNING:'AI诊断中',AI_SUGGESTED:'已有修复建议',AI_FAILED:'AI诊断失败',RETRYING:'验证中',RECOVERED:'已验证恢复',STILL_FAILING:'仍未恢复',CURRENT:'当日',STALE:'历史来源日',UNKNOWN:'来源日未知'}
const status=(s:string)=>labels[s]||s
const time=(value:any)=>{if(!value)return '—';const text=String(value).replace(' ','T');return new Date(/(Z|[+-]\d{2}:\d{2})$/i.test(text)?text:text+'Z').toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}
const toolName=(key:string)=>data.value?.tools.find((t:any)=>t.key===key)?.name||key
const filteredTargets=computed(()=>data.value?.targets.filter((t:any)=>`${t.name} ${t.source_url} ${t.field_scope}`.toLowerCase().includes(search.value.toLowerCase()))||[])
const filteredCandidates=computed(()=>data.value?.candidates.filter((t:any)=>`${t.name} ${t.fields} ${t.collectionMethod}`.toLowerCase().includes(search.value.toLowerCase()))||[])
const filteredRuns=computed(()=>runs.value.filter(r=>!failuresOnly.value||['FAILED','PARTIAL','INTERRUPTED'].includes(r.status)))
const profileField=(row:any,key:string)=>row?.latest?.profile?.[key]||''
const profileLine=(row:any,keys:string[])=>keys.map(key=>profileField(row,key)).filter(Boolean).join(' · ')
const entries=computed(()=>detail.value?.bundle_json?.observation?.entries||[])
const visibleEntries=computed(()=>entries.value.slice((page.value-1)*20,page.value*20))
const request=(path:string,method='GET',body?:unknown)=>profileRequest(base+path,{method,...(body!==undefined?{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})})
async function guard(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await action()}catch(e:any){error.value=e.message;ElMessage.error(e.message)}finally{busy.value=false}}
async function refresh(){const [overview,history,repairs,coverage]=await Promise.all([request(''),profileRequest('/api/v1/admin/ranking-capture/runs'),request('/repairs'),profileRequest('/api/v1/market/coverage')]);data.value=overview;runs.value=history;jobs.value=repairs;sourceSession.value=coverage.sync?.['source-session'];overseas.value=coverage.sync?.overseas}
const reload=()=>guard(refresh)
function edit(target?:any){editKey.value=target?.target_key||'';editingImplemented.value=!!target?.source_key||!!target?.onlineRule;Object.assign(form,{name:target?.name||'',url:target?.source_url||'',fields:target?.field_scope||'',notes:target?.notes||'',toolKey:target?.tool_key||'http-html',enabled:!!target?.enabled,revision:target?.revision||0});editOpen.value=true}
function register(candidate:any){edit();form.name=candidate.name;try{const u=new URL(candidate.url);form.url=u.origin+u.pathname}catch{form.url=''}form.fields=candidate.fields||'';form.notes=`目录 ${candidate.sourceId}；${candidate.collectionMethod}；${candidate.limitations}`;form.toolKey=String(candidate.collectionMethod).toLowerCase().includes('firecrawl')?'firecrawl':'http-html'}
async function save(){await guard(async()=>{await request('/targets'+(editKey.value?'/'+encodeURIComponent(editKey.value):''),editKey.value?'PUT':'POST',form);editOpen.value=false;await refresh();ElMessage.success('目标配置已保存')})}
function editSchedule(){Object.assign(schedule,{enabled:!!data.value.schedule.enabled,frequency:data.value.schedule.cron_expression.includes(';')?'twice':'daily',revision:data.value.schedule.revision});scheduleOpen.value=true}
async function saveSchedule(){await guard(async()=>{await request('/schedule','PUT',schedule);scheduleOpen.value=false;await refresh();ElMessage.success('定时计划已保存')})}
async function run(target?:any){await guard(async()=>{const r=await request('/run'+(target?'?target='+encodeURIComponent(target.target_key):''),'POST');await refresh();tab.value=target?.onlineRule?'web':'runs';ElMessage({message:`本次采集：${status(r.status)}，运行 ${r.batchId||r.id}`,type:r.status==='SUCCEEDED'?'success':'warning'})})}
async function view(id:number){await guard(async()=>{detail.value=await profileRequest('/api/v1/admin/ranking-capture/observations/'+id);page.value=1;detailOpen.value=true})}
async function createRepair(runId:string){await guard(async()=>{job.value=await request('/repairs','POST',{runId});jobOpen.value=true;await refresh()})}
function showJob(item:any){job.value=item;jobOpen.value=true}
async function diagnose(){try{await ElMessageBox.confirm('将发送来源URL、榜单范围、错误码、材料哈希和工具维护路径给已配置的AI服务。不发送页面原文、Cookie或浏览器会话。返回的是修复建议，仍需Agent修改代码并验证。','AI诊断',{confirmButtonText:'发送诊断',cancelButtonText:'取消',type:'info'})}catch{return}await guard(async()=>{job.value=await request(`/repairs/${job.value.id}/diagnose`,'POST');await refresh()})}
async function retry(){await guard(async()=>{job.value=await request(`/repairs/${job.value.id}/retry`,'POST');await refresh();ElMessage({message:`验证结果：${status(job.value.status)}`,type:job.value.status==='RECOVERED'?'success':'warning'})})}
async function loadPublicProfiles(){if(!publicObservationId.value)return ElMessage.warning('请输入微信或抖音榜单观察ID');publicProfileBusy.value=true;try{publicProfiles.value=await request(`/public-profiles/candidates?observationId=${publicObservationId.value}&limit=100`)}catch(e:any){ElMessage.error(e.message)}finally{publicProfileBusy.value=false}}
async function capturePublicProfiles(){if(!publicObservationId.value)return ElMessage.warning('请输入微信或抖音榜单观察ID');publicProfileBusy.value=true;try{const result=await request('/public-profiles/capture','POST',{observationId:publicObservationId.value,candidateExternalIds:[],limit:100});ElMessage({message:`公开资料：成功 ${result.succeeded}，失败 ${result.failed}，无候选 ${result.noCandidate}`,type:result.failed?'warning':'success'});await loadPublicProfiles()}catch(e:any){ElMessage.error(e.message)}finally{publicProfileBusy.value=false}}
function download(value:any,name:string){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(reload)
</script>

<template>
<section class="capture-page" aria-label="信息抓取工作台">
  <div class="capture-heading"><div><div class="eyebrow">外部数据 · 独立采集</div><h1>信息抓取</h1><p>管理来源、采集工具和运行结果，让每一条信息都有出处。</p></div><div class="actions"><el-button :disabled="busy" @click="reload">刷新状态</el-button><el-button type="primary" :loading="busy" :disabled="!data?.summary.enabledTargets" @click="run()">抓取服务器目标</el-button></div></div>
  <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="notice"/>
  <div v-if="!data" class="empty">{{busy?'正在读取采集配置与真实记录…':'暂无数据，请检查连接后刷新。'}}</div>
  <template v-else>
    <div class="metrics"><article><span>纳入采集的网站目标</span><strong>{{data.summary.enabledTargets}}<small> / {{data.summary.targetCount}}</small></strong><p>可在目标配置中调整范围</p></article><article><span>计划覆盖榜单</span><strong>{{data.summary.plannedCharts}}<small> 榜 × 100名</small></strong><p>每榜独立校验连续排名</p></article><article><span>最近运行完整榜单</span><strong>{{data.summary.completeCharts}}<small> / {{data.summary.plannedCharts}}</small></strong><p>完整榜共 {{data.summary.latestRows}} 条记录</p></article><article><span>定时采集</span><strong class="schedule-state">{{data.schedule.enabled?'已启用':'未启用'}}</strong><p>{{data.schedule.workerOnline?'执行器在线':'执行器离线 / 尚无心跳'}}</p></article></div>
    <div class="schedule-strip"><div><b>{{data.schedule.cron_expression.includes(';')?'每天 08:30、23:00':'每天 08:30'}} <span>北京时间</span></b><p>下次执行：{{time(data.schedule.next_due_at)}} · 执行器心跳：{{time(data.schedule.worker_seen_at)}}</p><p v-if="data.schedule.last_result_json">最近计划：{{status(data.schedule.last_result_json.status)}} · {{time(data.schedule.last_finished_at)}}</p></div><el-button :disabled="busy" @click="editSchedule">管理定时计划</el-button></div>
    <div class="schedule-strip source-session"><div><b>引力引擎 · 服务器登录维护</b><p>{{sessionNeedsLogin?'登录已失效：需要人工重新验证':sessionReviewDue?'建议续登：距上次登录验证已满6天':sourceSession?.status==='VERIFIED'?'已通过完整榜单采集验证':'等待服务器登录验证'}}</p><p>最近登录验证：{{time(sourceSession?.lastLoginVerifiedAt)}} · 建议下次检查：{{time(sourceSession?.reviewAfter)}}</p><p class="muted">源站会话约7天；实际可能提前失效。第6天提示检查，失败保留原数据。采集在服务器运行，无需个人电脑常开。</p></div><el-button :type="sessionNeedsLogin?'danger':sessionReviewDue?'warning':'primary'" @click="maintenanceOpen=true">续登说明</el-button></div>
    <el-dialog v-model="maintenanceOpen" title="服务器登录维护" width="min(680px,94vw)"><p>1. 在运维电脑打开项目目录，运行下方维护工具。工具会临时打开服务器浏览器；仅在登录期间使用本机。</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">powershell -ExecutionPolicy Bypass -File scripts/renew-server-capture-login.ps1</pre><p>2. 在远程窗口完成引力引擎短信或扫码登录，建议选择“7天免登录”。账号和验证码只在源站输入。</p><p>3. 返回维护工具按回车，它会保存会话、关闭临时窗口、执行真实榜单验证并恢复定时任务。成功后刷新本页查看验证时间。</p><p>维护工具需要已有服务器SSH配置。登录入口只通过临时安全隧道访问，未在公网开放远程桌面。维护完成后可关闭电脑。</p><p>如果取消或遗忘关闭，35分钟后服务端会清理登录窗口并恢复采集计划；未登录成功的来源保持失败，不生成假数据。</p></el-dialog>
    <div class="schedule-strip"><div><b>Google Play · 独立云端采集</b><p>每天北京时间 08:40、23:10（云端排队可能延迟）；按已启用地区采集免费、付费、畅销、新免费、新付费榜。</p><p>最近交付：{{overseas?status(overseas.status):'等待首次交付'}} · {{time(overseas?.receivedAt)}} · {{overseas?.importedEntries??0}}条 · 来源失败 {{overseas?.sourceFailedCount??0}} 个 · 部分覆盖 {{overseas?.sourcePartialCount??0}} 个</p><p>此处是最近交付回执，并非实时在线状态。停止某地区可在目标配置中关闭；云端失败保留历史，不把旧数据当今天。</p></div><a href="https://github.com/Mrmocao/game-rank-capture/actions/workflows/overseas-capture.yml" target="_blank" rel="noopener noreferrer">查看云端任务与失败日志 ↗</a></div>
    <el-alert :title="data.notice" type="info" :closable="false" class="notice"/>
    <el-tabs v-model="tab" class="capture-tabs">
      <el-tab-pane label="公开资料补充" name="public-profiles" lazy>
        <div class="insight-panel public-profile-panel"><h2>按榜单游戏名称读取公开基本资料</h2><p class="muted">从现有微信/抖音榜单观察中逐行匹配中国 iOS 应用索引，再读取七麦公开详情页。候选身份保持未核验；不读取登录后数据，不把下载预估写回小游戏指标。</p><div class="toolbar"><el-input-number v-model="publicObservationId" :min="1" controls-position="right" placeholder="榜单观察ID" aria-label="榜单观察ID"/><el-button :loading="publicProfileBusy" @click="loadPublicProfiles">读取候选</el-button><el-button type="primary" :loading="publicProfileBusy" @click="capturePublicProfiles">抓取公开详情</el-button></div><el-alert v-if="publicProfiles?.notice" :title="publicProfiles.notice" type="info" :closable="false"/><el-table v-if="publicProfiles" :data="publicProfiles.rows" stripe><el-table-column label="原榜" min-width="220"><template #default="{row}">{{row.seed?.rank_position}} · {{row.seed?.name}}<div class="muted">{{row.seed?.developer||'发行方未知'}}</div></template></el-table-column><el-table-column label="iOS候选" min-width="270"><template #default="{row}"><div v-for="m in row.matches" :key="m.candidate_external_id">{{m.candidate_name}} · {{m.candidate_external_id}}<div class="muted">{{m.candidate_developer}}</div></div><span v-if="!row.matches?.length" class="muted">无名称候选</span></template></el-table-column><el-table-column label="公开资料字段" min-width="300"><template #default="{row}"><template v-if="row.latest?.profile"><b>{{row.latest.profile.name}}</b><div class="muted">{{profileLine(row,['developer','categoryDisplay','priceDisplay'])}}</div><div class="muted">评分 {{row.latest.profile.ratingDisplay||'未知'}}（{{row.latest.profile.ratingCountDisplay||'未知'}}） · 昨日下载 {{row.latest.profile.yesterdayDownloadsDisplay||'未知'}}</div><div class="muted">更新 {{row.latest.profile.updatedDateDisplay||'未知'}} · 发布 {{row.latest.profile.firstReleaseDateDisplay||'未知'}}</div></template><span v-else class="muted">尚未取得字段</span></template></el-table-column><el-table-column label="采集状态" min-width="210"><template #default="{row}"><span v-if="row.latest">{{status(row.latest.status)}} · {{row.latest.candidate_name||'无候选'}}<div class="muted">{{time(row.latest.captured_at)}} · {{row.latest.error_code||'字段已保存'}}</div></span><span v-else class="muted">尚未抓取</span></template></el-table-column></el-table><el-empty v-else description="输入榜单观察ID后读取候选"/></div>
      </el-tab-pane>
      <el-tab-pane label="下载与付费信息" name="metrics" lazy><GameMetricCapture v-if="tab==='metrics'"/></el-tab-pane>
      <el-tab-pane label="在线规则 / Firecrawl" name="web" lazy><OnlineWebCapture @changed="reload"/></el-tab-pane>
      <el-tab-pane label="抓取目标" name="targets">
        <div class="toolbar"><el-input v-model="search" placeholder="搜索网站、名称或信息字段" clearable aria-label="搜索抓取目标"/><el-button :disabled="busy" @click="edit()">登记新网站</el-button></div>
        <el-table :data="filteredTargets" stripe class="target-table" row-key="target_key">
          <el-table-column label="网站与来源" min-width="230"><template #default="{row}"><b>{{row.name}}</b><a :href="row.source_url" target="_blank" rel="noopener noreferrer" class="source-link">{{row.source_url}}</a><div class="tags"><el-tag size="small" :type="row.implemented?'success':'info'">{{row.onlineRule?'在线规则可配置':row.implemented?'适配器已实现':'待接入'}}</el-tag><span>{{row.authority}}</span></div></template></el-table-column>
          <el-table-column label="获取内容与方法" min-width="250"><template #default="{row}"><p>{{row.field_scope}}</p><el-tag size="small">{{toolName(row.tool_key)}}</el-tag><p class="muted">{{row.chartCount}}个榜单 · {{row.enabled?'纳入定时范围':'未纳入定时范围'}}{{row.browserRequired?' · 复用服务器登录':''}}</p></template></el-table-column>
          <el-table-column label="最近一次各榜运行" min-width="230"><template #default="{row}"><div v-for="r in row.latestRuns" :key="r.id" class="chart-status"><el-button link type="primary" :disabled="!r.observation_id||r.status==='FAILED'" @click="view(r.observation_id)">{{r.chart_key}}</el-button><span>{{status(r.status)}} {{r.actual_count??0}}/100</span><small>{{r.business_date||'日期未知'}} · {{status(r.freshness)}}</small></div><span v-if="!row.latestRuns.length" class="muted">尚无执行记录，未验证在线可用性</span></template></el-table-column>
          <el-table-column label="管理" width="135"><template #default="{row}"><el-button link type="primary" :disabled="busy" @click="edit(row)">配置</el-button><a v-if="row.remoteWorkflowUrl" :href="row.remoteWorkflowUrl" target="_blank" rel="noopener noreferrer">云端运行 ↗</a><el-button v-else link type="primary" :disabled="busy||!row.executionReady" @click="run(row)">立即抓取</el-button></template></el-table-column>
        </el-table>
      </el-tab-pane>
      <el-tab-pane label="抓取工具" name="tools">
        <p class="muted">普通网页与Firecrawl支持在线规则编辑、试抓和发布，无需重新部署。已有专用榜单适配器仍保留独立代码校验。</p>
        <el-button type="primary" @click="tab='web'">配置Firecrawl / 在线规则</el-button>
        <div class="tools-grid"><article v-for="tool in data.tools" :key="tool.key" class="tool-card"><div class="tool-title"><h3>{{tool.name}}</h3><el-tag :type="tool.implemented?'success':'info'">{{tool.implemented?'已实现':'待接入'}}</el-tag></div><code>{{tool.key}}</code><p>{{tool.method}}</p><p class="muted">绑定 {{data.targets.filter((t:any)=>t.tool_key===tool.key).length}} 个目标 · {{tool.repairBoundary}}</p><details><summary>维护位置与验证命令</summary><ul><li v-for="file in tool.files" :key="file"><code>{{file}}</code></li></ul><pre>{{tool.validation}}</pre></details></article></div>
      </el-tab-pane>
      <el-tab-pane label="执行记录" name="runs">
        <div class="toolbar"><p>最近200次真实运行；来源日期与采集时间分别保留。</p><el-checkbox v-model="failuresOnly">只看失败或不完整</el-checkbox></div>
        <el-table :data="filteredRuns" stripe max-height="650"><el-table-column label="来源 / 榜单" min-width="200"><template #default="{row}"><b>{{row.source_key}}</b><p>{{row.chart_key}} · {{row.region}}</p></template></el-table-column><el-table-column label="执行时间（北京）" min-width="180"><template #default="{row}">{{time(row.started_at)}}</template></el-table-column><el-table-column label="结果" min-width="170"><template #default="{row}"><el-tag :type="row.status==='SUCCEEDED'?'success':row.status==='RUNNING'?'info':'warning'">{{status(row.status)}}</el-tag><p>{{row.result_json?.entries??0}} / {{row.requested_top_n}} · {{status(row.freshness)}}</p><small>{{row.error_code}}</small></template></el-table-column><el-table-column label="来源日期" min-width="120"><template #default="{row}">{{row.result_json?.businessDate||'未知'}}</template></el-table-column><el-table-column label="操作" width="190"><template #default="{row}"><el-button link type="primary" :disabled="!row.observation_id||row.status==='FAILED'||busy" @click="view(row.observation_id)">查看数据</el-button><el-button v-if="['FAILED','PARTIAL','INTERRUPTED'].includes(row.status)" link type="primary" :disabled="busy" @click="createRepair(row.id)">修复工单</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane label="AI修复" name="repairs">
        <el-alert title="修复流程：失败记录 → 创建工单 → AI诊断 / Agent交接 → 修改独立工具 → 实际重试。AI建议不会自动执行或发布代码，只有完整抓取成功才标记恢复。" type="info" :closable="false"/>
        <p>AI服务：{{data.ai.enabled&&data.ai.configured?data.ai.model:'未启用或未配置'}} <a href="#/collection">前往工具与接入配置</a></p>
        <el-empty v-if="!jobs.length" description="尚无修复工单，可在执行记录中为失败或不完整运行创建。"/>
        <el-table v-else :data="jobs" stripe><el-table-column prop="target_key" label="目标" min-width="150"/><el-table-column prop="tool_key" label="工具" min-width="140"/><el-table-column prop="error_code" label="问题" min-width="210"/><el-table-column label="进展" min-width="150"><template #default="{row}">{{status(row.status)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="showJob(row)">查看工单</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane :label="`来源目录（${data.candidates.length}）`" name="candidates">
        <p class="muted">以下为来源研究目录，不等于已接入。第三方引力引擎不代表微信/抖音官方数据，AppBrain也不代表Google Play官方接口。</p>
        <div class="toolbar"><el-input v-model="search" placeholder="搜索平台、信息字段或获取方式" clearable aria-label="搜索来源目录"/></div>
        <el-table :data="filteredCandidates" stripe max-height="650"><el-table-column label="平台 / 验证级别" min-width="240"><template #default="{row}"><a :href="row.url" target="_blank" rel="noopener noreferrer">{{row.sourceId}} · {{row.name}}</a><p>{{row.accessType}} · {{row.verificationLevel}}</p><el-tag v-if="row.sourceId==='S03'" size="small" type="success">Apple RSS已接入中国游戏免费榜</el-tag><span v-else class="muted">候选研究 / 按范围接入</span></template></el-table-column><el-table-column prop="fields" label="可获取信息" min-width="220"/><el-table-column label="方式与限制" min-width="300"><template #default="{row}"><p>{{row.collectionMethod}}</p><small>{{row.limitations}}</small></template></el-table-column><el-table-column label="管理" width="120"><template #default="{row}"><el-button link type="primary" @click="register(row)">登记为目标</el-button></template></el-table-column></el-table>
      </el-tab-pane>
    </el-tabs>
  </template>

  <el-dialog v-model="editOpen" :title="editKey?'配置抓取目标':'登记新网站'" width="min(620px, 94vw)" :close-on-click-modal="false">
    <el-form label-position="top"><el-form-item label="目标名称"><el-input v-model="form.name" maxlength="200"/></el-form-item><el-form-item label="网站入口（HTTPS，不含凭证或查询参数）"><el-input v-model="form.url" :disabled="editingImplemented" maxlength="1000"/></el-form-item><el-form-item label="抓取工具"><el-select v-model="form.toolKey" :disabled="editingImplemented"><el-option v-for="t in data?.tools||[]" :key="t.key" :value="t.key" :label="t.name"/></el-select></el-form-item><el-form-item label="需要获取的信息"><el-input v-model="form.fields" type="textarea" :rows="3" maxlength="4000"/></el-form-item><el-form-item label="备注 / 来源限制"><el-input v-model="form.notes" type="textarea" maxlength="4000"/></el-form-item><el-form-item label="纳入定时采集范围"><el-switch v-model="form.enabled" :disabled="!editingImplemented"/><span class="muted">　普通网页/Firecrawl须先在在线规则中试抓并发布；登记不会自动执行。</span></el-form-item></el-form><template #footer><el-button @click="editOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存目标</el-button></template>
  </el-dialog>
  <el-dialog v-model="scheduleOpen" title="管理定时计划" width="min(540px, 94vw)" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="启用自动抓取"><el-switch v-model="schedule.enabled"/></el-form-item><el-form-item label="抓取频率 · Asia/Shanghai"><el-radio-group v-model="schedule.frequency"><el-radio value="daily">每天08:30</el-radio><el-radio value="twice">每天08:30、23:00</el-radio></el-radio-group></el-form-item></el-form><p class="muted">执行器在服务器运行，抓取时需要来源登录会话有效。离线后恢复会补跑一次到期任务，不重复补跑所有错过时段；抓取失败会保留历史成功数据。</p><template #footer><el-button @click="scheduleOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveSchedule">保存计划</el-button></template></el-dialog>
  <el-drawer v-model="detailOpen" title="来源榜单数据" size="min(960px, 96vw)">
    <template v-if="detail"><h2>{{detail.bundle_json.observation.boardName}}</h2><p>{{detail.bundle_json.observation.sourceKey}} · {{detail.bundle_json.observation.region}} · 来源日 {{detail.bundle_json.observation.sourceDate||'未提供'}} · 业务日 {{detail.bundle_json.observation.businessDate||'未知'}}</p><p>采集于 {{time(detail.bundle_json.evidence.capturedAt)}} · 实际 {{entries.length}} 条 · 连续前 {{detail.bundle_json.coverage.contiguousTopN}} 名</p><a :href="detail.bundle_json.evidence.sourceUrl" target="_blank" rel="noopener noreferrer">打开原始来源</a><el-button class="download" @click="download(detail.bundle_json,`capture-${detail.id}.json`)">下载完整JSON</el-button><p v-if="detail.bundle_json.observation.warnings?.length" class="muted">{{detail.bundle_json.observation.warnings.join('；')}}</p><p class="muted">下方商店指标是最新补充，不代表榜单当天快照；售价不是收入。<el-button link type="primary" :loading="observationMetricsLoading" @click="refreshObservationMetrics">刷新补充指标</el-button></p><el-alert v-if="observationMetricsError" :title="'补充指标加载失败：'+observationMetricsError" type="error" :closable="false"/><el-table :data="visibleEntries" stripe><el-table-column prop="rank" label="排名" width="70"/><el-table-column prop="name" label="名称" min-width="170"/><el-table-column prop="developer" label="开发者 / 发行方" min-width="180"/><el-table-column prop="externalId" label="来源ID" min-width="130"/><RankingMetricColumns :rows="observationMetrics" :loading="observationMetricsLoading" :error="observationMetricsError" @inspect="inspectMetric"/></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="entries.length" layout="prev, pager, next, total"/><details><summary>证据与来源字段</summary><p class="hash">SHA256 {{detail.bundle_json.evidence.sha256}}</p><pre>{{JSON.stringify(detail.bundle_json.observation.entries[(page-1)*20]?.sourceFields||{},null,2)}}</pre></details></template>
  </el-drawer>
  <el-drawer v-model="jobOpen" title="抓取修复工单" size="min(780px, 96vw)">
    <template v-if="job"><h2>{{job.target_key}} · {{status(job.status)}}</h2><p>问题：{{job.error_code}} · 工具：{{job.tool_key}}</p><el-alert v-if="job.status==='NEEDS_LOGIN'" title="登录会话已失效，请运行 scripts/login-ranking-capture.ps1 手工登录，然后点击实际重试。" type="warning" :closable="false"/><div class="actions job-actions"><el-button :disabled="busy||!data.ai.enabled||!data.ai.configured||['NEEDS_LOGIN','AI_RUNNING','RETRYING','RECOVERED'].includes(job.status)" @click="diagnose">AI诊断</el-button><el-button @click="download(job,`capture-agent-${job.id}.json`)">下载Agent交接包</el-button><el-button type="primary" :disabled="busy||['AI_RUNNING','RETRYING','RECOVERED'].includes(job.status)" :loading="busy" @click="retry">实际重试验证</el-button></div><p class="muted">交接包交给有代码访问权的Agent使用。建议生成不代表修复完成，系统不会执行模型返回的任意代码。</p><el-alert v-if="job.ai_error_code" :title="job.ai_error_code" type="warning" :closable="false"/><template v-if="job.proposal_json"><h3>诊断</h3><p>{{job.proposal_json.diagnosis}}</p><p v-if="job.proposal_json.requiresHumanLogin">AI建议先由用户重新登录。</p><h3>修改建议</h3><ul><li v-for="(item,i) in job.proposal_json.changes" :key="i">{{item}}</li></ul><h3>验证步骤</h3><ul><li v-for="(item,i) in job.proposal_json.checks" :key="i">{{item}}</li></ul></template><p v-if="job.retry_batch_id">验证批次：{{job.retry_batch_id}}</p><details open><summary>脱敏诊断上下文</summary><pre>{{JSON.stringify(job.context_json,null,2)}}</pre></details></template>
  </el-drawer>
<RankingMetricEvidence v-model="metricOpen" :row="metricRow"/>
</section>
</template>

